/**
* Applies a forward sequence of plane rotations to a real matrix A, from the left side with variable pivot.
*
* @private
* @param {NonNegativeInteger} M - number of rows of `A`
* @param {NonNegativeInteger} N - number of columns of `A`
* @param {Float64Array} C - array of cosines of the plane rotations
* @param {integer} strideC - stride for `C`
* @param {NonNegativeInteger} offsetC - starting index for `C`
* @param {Float64Array} S - array of sines of the plane rotations
* @param {integer} strideS - stride for `S`
* @param {NonNegativeInteger} offsetS - starting index for `S`
* @param {Float64Array} A - input/output matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @returns {Float64Array} matrix `A` after updating values
*/
function leftVariableForward( M, N, C, strideC, offsetC, S, strideS, offsetS, A, strideA1, strideA2, offsetA ) {
	var ctemp;
	var stemp;
	var temp;
	var idx0;
	var idx1;
	var idx2;
	var idx3;
	var idx4;
	var i;
	var j;

	idx0 = offsetC;
	idx1 = offsetS;
	idx2 = offsetA;
	for ( j = 0; j < M - 1; j++ ) {
		ctemp = C[ idx0 ];
		stemp = S[ idx1 ];
		if ( ctemp !== 1.0 || stemp !== 0.0 ) {
			idx3 = idx2;
			for ( i = 0; i < N; i++ ) {
				idx4 = idx3 + strideA1;
				temp = A[ idx4 ];
				A[ idx4 ] = ( ctemp * temp ) - ( stemp * A[ idx3 ] );
				A[ idx3 ] = ( stemp * temp ) + ( ctemp * A[ idx3 ] );
				idx3 += strideA2;
			}
		}
		idx0 += strideC;
		idx1 += strideS;
		idx2 += strideA1;
	}

	return A;
}

